// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the functions we need
interface IOptiFi {
    function owner() external view returns (address);
    function setBotBlacklist(address _botAddress, bool _flag) external;
    function blacklist(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xb5D5D9C8E98cef68E7bdAd92b1De229d514179b6;
    address attacker = address(this);
    // No additional state variables needed

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get the owner dynamically
        // The test framework already provides TARGET constant and attacker address
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        address contractOwner = IOptiFi(TARGET).owner();

        // Impersonate the owner to call setBotBlacklist
        vm.prank(contractOwner);
        IOptiFi(TARGET).setBotBlacklist(TARGET, true);

        // Verify the blacklist status is true
        bool isBlacklisted = IOptiFi(TARGET).blacklist(TARGET);
        require(isBlacklisted, "Target should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }

    // No helper functions needed
    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

